def solve_stacks(total_chairs: int, num_students: int) -> int:
    if total_chairs <= num_students:
        return 0
    else:
        return (total_chairs - num_students) // 2

def max_revenue(available_lemonade, available_fries, combo_a_price, combo_a_lemonade, combo_a_fries, combo_b_price, combo_b_lemonade, combo_b_fries):
    max_revenue = 0
    for combo_a in range(available_lemonade // combo_a_lemonade + 1):
        for combo_b in range(available_lemonade // combo_b_lemonade + 1):
            for combo_a_fries_sold in range(available_fries // combo_a_fries + 1):
                for combo_b_fries_sold in range(available_fries // combo_b_fries + 1):
                    revenue = (combo_a * combo_a_price + combo_b * combo_b_price) * 1000
                    if revenue > max_revenue:
                        max_revenue = revenue
    return max_revenue

from itertools import combinations

def solve_octagon_prob(nums: list[int]) -> int:
    def is_right_triangle(a: int, b: int, c: int) -> bool:
        return a**2 + b**2 == c**2 or a**2 + c**2 == b**2 or b**2 + c**2 == a**2

    def is_arithmetic_progression(a: int, b: int, c: int) -> bool:
        return (b - a) * (c - b) == 0

    count = 0
    for triangle in combinations(nums, 3):
        if is_right_triangle(*triangle) and is_arithmetic_progression(*triangle):
            count += 1
    return count + 1

def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    total_revenue = 0
    products_sold = 0
    while True:
        total_revenue = fixed_cost + (products_sold * (selling_price - variable_cost))
        if products_sold < 100:
            total_revenue += (products_sold * 0.1 * selling_price)
        elif 100 <= products_sold < 300:
            total_revenue += (products_sold * 0.08 * selling_price)
        else:
            total_revenue += (products_sold * 0.05 * selling_price)
        if total_revenue > fixed_cost:
            return products_sold
        products_sold += 1

def total_pages_written(starting_pages: int, daily_increment: int) -> int:
    total_pages = 0
    for day in range(1, 8):
        total_pages += starting_pages + (day - 1) * daily_increment
    return total_pages

def max_charity_revenue(milk_tea_capacity: int, cake_capacity: int, menu1_price: int, menu1_items: tuple, menu2_price: int, menu2_items: tuple) -> int:
    dp = [[0] * (cake_capacity + 1) for _ in range(milk_tea_capacity + 1)]

    for i in range(1, milk_tea_capacity + 1):
        for j in range(1, cake_capacity + 1):
            menu1_items_made = min(i // menu1_items[0], j // menu1_items[1])
            menu2_items_made = min(i // menu2_items[0], j // menu2_items[1])
            dp[i][j] = max(
                dp[i][j],
                menu1_items_made * menu1_price + dp[i - menu1_items_made * menu1_items[0]][j - menu1_items_made * menu1_items[1]],
                menu2_items_made * menu2_price + dp[i - menu2_items_made * menu2_items[0]][j - menu2_items_made * menu2_items[1]]
            )

    return dp[milk_tea_capacity][cake_capacity]

def maximize_revenue(units: int, initial_rent: float, rent_increase: float, vacant_units_per_increase: int) -> float:
    max_revenue = 0.0
    max_rent = 0.0
    for rent in range(int(initial_rent), int(initial_rent) + units * rent_increase, int(rent_increase)):
        revenue = (initial_rent + (rent - initial_rent) / rent_increase) * units - (rent - initial_rent) * vacant_units_per_increase / rent_increase
        if revenue > max_revenue:
            max_revenue = revenue
            max_rent = rent / 1000000.0
    return max_rent

def count_ap_triplets(n: int, limit: int) -> int:
    count = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            for k in range(j + 1, n + 1):
                if i + j + k <= limit and (j - i) == (k - j):
                    count += 1
    return count

from typing import List
from itertools import combinations

def count_grid_ways(numbers: List[int]) -> int:
    if len(numbers) < 6:
        return 0

    target_sum = sum(numbers) // 3
    if target_sum * 3 != sum(numbers):
        return 0

    ways = 0
    for combination in combinations(numbers, 6):
        if sum(combination[:3]) == target_sum and sum(combination[3:5]) == target_sum and combination[5] == target_sum:
            ways += 1

    return ways

def maximize_profit(c0: float, c1: float, c2: float, c3: float, p0: float, p1: float) -> int:
    def profit(x: int) -> float:
        return (p0 - p1 * x) * x - (c0 + c1 * x - c2 * x**2 + c3 * x**3)

    max_profit = float('-inf')
    max_x = 0
    for x in range(1000):  # assuming the factory can't produce more than 1000 products
        profit_value = profit(x)
        if profit_value > max_profit:
            max_profit = profit_value
            max_x = x
    return max_x
